  order=sorted(pieces,key=lambda k:(max(r for r,c in pieces[k][1]) if direction==1 else min(r for r,c in pieces[k][1]))*direction, reverse=True)
  for key in order:
   color,cells=pieces[key]; proposal=[(r+direction,c) for r,c in cells]
   if (direction==1 and max(r for r,c in proposal)>=barrier) or (direction==-1 and min(r for r,c in proposal)<=barrier): continue
   if any(p in occupied and p not in cells for p in proposal): continue
   occupied.difference_update(cells); occupied.update(proposal); pieces[key]=(color,proposal); moved=True
  if not moved: break
 return pieces
