def slide(pieces, dr, dc, bound):
 for _ in range(100):
  moved=False; occ={p for _,cells in pieces.values() for p in cells}
  # order closest to destination first
  if dr>0: key=lambda x:max(r for r,c in pieces[x][1])
  elif dr<0: key=lambda x:min(r for r,c in pieces[x][1])
  elif dc>0: key=lambda x:max(c for r,c in pieces[x][1])
  else: key=lambda x:min(c for r,c in pieces[x][1])
  order=sorted(pieces,key=key,reverse=(dr>0 or dc>0))
  for k in order:
   col,cells=pieces[k]; q=[(r+dr,c+dc) for r,c in cells]
   if any(r<bound[0] or r>=bound[1] or c<bound[2] or c>=bound[3] for r,c in q):continue
   if any(p in occ and p not in cells for p in q):continue
   occ.difference_update(cells);occ.update(q);pieces[k]=(col,q);moved=True
  if not moved:break
 return pieces
